## Headless smoke test — runs WITHOUT the editor, WITHOUT GUT, in CI:
##   godot --headless -s tests/smoke_test.gd
##
## Asserts THE load-bearing guarantee of Ghost Company (sim.gd):
##   same encounter + same commands => identical state hash, twice in a row.
## Ghost replay correctness rides on this: a ghost that mismatches its
## recording is impossible if this test is green.
##
## Tests 4-6 (v1, Nov 3 2026): the full 3-round battle loop via TurnManager —
## determinism of the loop, ghost spawn presence, victory-by-echo routing.

const MARKSMAN_ATK: int = 3   # from encounter_01.json — kept here as a named constant

func _initialize() -> void:
	var failures: Array = []
	var encounter: Dictionary = _load_encounter()

	# --- Test 1: determinism (run the same battle script twice, hashes must match)
	var hash_a: int = _run_battle_script(encounter)
	var hash_b: int = _run_battle_script(encounter)
	if hash_a != hash_b:
		failures.append("DETERMINISM FAIL: hash_a=%d hash_b=%d" % [hash_a, hash_b])

	# --- Test 2: ghost replay — replay a recording against a fresh board,
	#     outcome must also be byte-identical across two replays.
	var replay_a: int = _run_ghost_replay(encounter)
	var replay_b: int = _run_ghost_replay(encounter)
	if replay_a != replay_b:
		failures.append("GHOST REPLAY NONDETERMINISM: %d vs %d" % [replay_a, replay_b])

	# --- Test 3: attack resolves damage (shade_a: 5 hp - marksman 3 atk = 2, alive)
	var sim := _fresh_sim(encounter)
	sim.issue_command("marksman", "attack", {"x": 6, "y": 3})
	if int(sim.units["shade_a"]["hp"]) != 2 or not sim.units["shade_a"]["alive"]:
		failures.append("ATTACK FAIL: shade_a expected hp=2 alive, got hp=%d alive=%s" % [
			int(sim.units["shade_a"]["hp"]), sim.units["shade_a"]["alive"]])

	# --- Test 4: full battle loop determinism (run the whole battle twice)
	var battle_a: Dictionary = _run_full_battle(encounter)
	var battle_b: Dictionary = _run_full_battle(encounter)
	if battle_a["hash"] != battle_b["hash"] or battle_a["ended"] != battle_b["ended"] \
			or battle_a["victory"] != battle_b["victory"]:
		failures.append("BATTLE LOOP NONDETERMINISM: %s vs %s" % [
			JSON.stringify(battle_a), JSON.stringify(battle_b)])

	# --- Test 5: round 2 spawns ghost units for the recorded squad
	if int(battle_a["ghosts_round2"]) != 3:
		failures.append("GHOST SPAWN FAIL: expected 3 ghost units in round 2, got %d" % [
			int(battle_a["ghosts_round2"])])

	# --- Test 6: the echo routes the wave in round 2 => victory fires
	if not battle_a["ended"] or not battle_a["victory"]:
		failures.append("BATTLE LOOP FAIL: expected victory by echo in round 2, got %s" % [
			JSON.stringify(battle_a)])

	if failures.is_empty():
		print("SMOKE TEST: all green (det=%d replay=%d battle_hash=%d victory=%s)" % [
			hash_a, replay_a, battle_a["hash"], battle_a["victory"]])
		quit(0)
	else:
		for f in failures:
			push_error(f)
		quit(1)

func _load_encounter() -> Dictionary:
	var f := FileAccess.open("res://data/encounters/encounter_01.json", FileAccess.READ)
	var parsed = JSON.parse_string(f.get_as_text())
	assert(parsed is Dictionary)
	return parsed

func _fresh_sim(encounter: Dictionary) -> RefCounted:
	var sim: RefCounted = load("res://scripts/sim/sim.gd").new(
		int(encounter["grid_w"]), int(encounter["grid_h"]), int(encounter["seed"]))
	for u in encounter["units"]:
		sim.add_unit(u.duplicate(true))
	return sim

## A fixed "player script" standing in for input during the prototype phase.
func _run_battle_script(encounter: Dictionary) -> int:
	var sim := _fresh_sim(encounter)
	sim.issue_command("skirmisher", "move", {"x": 3, "y": 5})
	sim.issue_command("lineholder", "move", {"x": 2, "y": 3})
	sim.issue_command("marksman", "attack", {"x": 6, "y": 3})
	sim.issue_command("marksman", "move", {"x": 2, "y": 4})
	sim.issue_command("marksman", "attack", {"x": 6, "y": 3})
	return sim.state_hash()

func _run_ghost_replay(encounter: Dictionary) -> int:
	var sim := _fresh_sim(encounter)
	# "Round 1 commands" — recorded:
	sim.issue_command("skirmisher", "move", {"x": 3, "y": 5})
	var recording: Array = sim.commands.duplicate(true)
	# Fresh board (round 2), ghost replays:
	var sim2 := _fresh_sim(encounter)
	sim2.replay(recording)
	return sim2.state_hash()

## Test 4-6 driver: one scripted battle through the TurnManager.
## Round 1: living squad focus-fires (v0 sim: attacks target cells, no range).
## Round 2: the fresh wave respawns at the same cells — Echo 1 replays the
## same attacks into it: 3+2+1 = 6 >= each shade's 5 hp on its target cell,
## so the echo alone routs the wave; end_round() then declares victory.
func _run_full_battle(encounter: Dictionary) -> Dictionary:
	var tm: RefCounted = load("res://scripts/battle/turn_manager.gd").new()
	var result: Dictionary = {"ended": false, "victory": false, "ghosts_round2": 0, "hash": 0}
	tm.battle_ended.connect(func(victory: bool) -> void:
		result["ended"] = true
		result["victory"] = victory)
	tm.start_battle(encounter)
	# Round 1 orders:
	tm.on_player_command("marksman", "attack", {"x": 6, "y": 3})   # shade_a cell
	tm.on_player_command("lineholder", "attack", {"x": 6, "y": 4}) # shade_b cell
	tm.on_player_command("skirmisher", "attack", {"x": 6, "y": 4}) # shade_b cell
	tm.end_round()
	# Round 2 has started (ghosts replayed at round start). Count them:
	var ghost_count: int = 0
	for id in tm.sim.units.keys():
		if tm.sim.units[id].get("ghost", false):
			ghost_count += 1
	result["ghosts_round2"] = ghost_count
	result["hash"] = tm.sim.state_hash()
	# Empty orders for round 2 — the echo already did the work; ending evaluates:
	tm.end_round()
	# Battle must be over now; further calls must be safe no-ops:
	tm.end_round()
	tm.on_player_command("marksman", "attack", {"x": 0, "y": 0})
	return result
